sql-service.query:
BEGIN TRANSACTION; UPDATE A SET TA_FLAG=?TA_FLAG, GRD_FLAG=?GRD_FLAG, ASS_FLAG=?ASS_FLAG, ENC_FLAG=?ENC_FLAG, VRS_S_FLAG=?VRS_S_FLAG, BAN_S_FLAG=?BAN_S_FLAG, CHG_ID = 'INF130', CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM MS_STT_META A, MS_STT_RSLT_MERGE B WHERE A.UCID=B.UCID AND A.UCID = ?UCID AND A.CON_ENT_DGN_NO = ?CON_ENT_DGN_NO
UPDATE B SET B.ENC_FLAG= ?ENC_FLAG, B.CHG_ID ='INF130', B.CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM MS_STT_META A, MS_STT_RSLT_MERGE B WHERE A.UCID=B.UCID AND A.UCID = ?UCID AND A.CON_ENT_DGN_NO = ?CON_ENT_DGN_NO
COMMIT;
